/* Custom Overlay Animations Blended with Donatex Theme */
.obs-overlay-container {
  margin: 0;
  padding: 0;
  overflow: hidden;
  position: relative;
  width: 100%;
  height: 100vh;
}

.obs-float-emoji {
  position: absolute;
  bottom: 8%;
  left: var(--float-start-x, 50%);
  z-index: 5;
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 1;
  pointer-events: none;
  user-select: none;
  will-change: transform, opacity;
  animation: obs-float-path var(--float-duration, 3500ms) ease-out forwards;
}

@keyframes obs-float-path {
  0% {
    transform: translate3d(0, 12vh, 0) scale(0.7);
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  70% {
    opacity: 1;
  }
  100% {
    transform: translate3d(var(--float-drift-x, 0vw), -78vh, 0) scale(1.15);
    opacity: 0;
  }
}

